package run.ikaros.finance; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class AccountLifecycleService{private final AccountRepository accounts;private final FinanceLedgerAccessService access;public AccountLifecycleService(AccountRepository a,FinanceLedgerAccessService x){accounts=a;access=x;}public Mono<AccountView> setArchived(UUID actor,UUID id,boolean archived){return accounts.findById(id).switchIfEmpty(Mono.error(new NotFoundException("Account 不存在或无权访问"))).flatMap(a->access.requireEditor(actor,a.ledgerId()).then(accounts.save(new AccountEntity(a.id(),a.ledgerId(),a.ownerId(),a.name(),a.type(),a.currency(),a.openingBalance(),a.currentBalance(),a.institution(),a.maskedIdentifier(),a.credentialRef(),archived,a.createdAt(),Instant.now(),a.version())))).map(this::view);}private AccountView view(AccountEntity a){return new AccountView(a.id(),a.ledgerId(),a.name(),a.type(),a.currency(),a.openingBalance(),a.currentBalance(),a.institution(),a.maskedIdentifier(),a.credentialRef(),a.archived(),a.createdAt());}}
